from __future__ import annotations

import base64
import gzip
from pathlib import Path

PAYLOADS = {
    "android-app/app/src/main/java/io/github/xgl34222220/luoshu/ui/home/DeviceAcceptanceGuide.kt": "",
    "common/util_functions.sh": "",
    "common/device_font_cache.sh": "",
}

for path, encoded in PAYLOADS.items():
    target = Path(path)
    target.write_bytes(gzip.decompress(base64.b64decode(encoded)))

for temporary in (
    ".github/workflows/apply-v226-hotfix.yml",
    ".github/workflows/apply-v226-hotfix-pr.yml",
    ".github/workflows/apply-v226-hotfix-pr2.yml",
    ".github/v226-hotfix-trigger",
    ".github/apply_v226_payload.py",
):
    Path(temporary).unlink(missing_ok=True)
